        { "Security_Migrate_Body", "This will upgrade the database to the new AES-256-GCM encryption format. After the upgrade, the database can only be opened with Novara 3.0 or newer. Uninstalling back to 2.0 will make all data unreadable. Upgrade now?" },
        { "Security_Migrate_Confirm", "Upgrade" },
        { "Security_Migrate_Kdf_Title", "Upgrade Encryption Strength" },
        { "Security_Migrate_Kdf_Body", "This database still uses the legacy encryption parameters (PBKDF2, 100,000 iterations). The new default is 3,000,000 iterations, which greatly raises the cost of brute-force attacks. Upgrading re-encrypts the database (about 1 second). ⚠️ After upgrading, 5.2.0 and earlier versions cannot open this database (desktop sticky notes, the MCP interface and backup files are unaffected). Unlocking the database will produce a noticeable wait; low-end devices will see longer delays. Upgrade now?" },
