        { "Security_Migrate_Kdf_Body", "이 데이터베이스는 이전 암호화 매개변수(PBKDF2 100,000회)를 사용합니다. 새 기본값은 3,000,000회로 무차별 대입 공격 비용을 크게 높입니다. 업그레이드 시 데이터베이스를 다시 암호화합니다(약 1초). ⚠️ 업그레이드 후 5.2.0 이하 버전에서는 이 데이터베이스를 열 수 없습니다(데스크톱 스티커, MCP 인터페이스, 백업 파일은 영향 없음). 업그레이드 후 데이터베이스 잠금 해제 시 체감되는 대기 시간이 발생하며, 저사양 기기에서는 지연이 더 길어집니다. 업그레이드하시겠습니까?" },
