        { "Sync_Pair_Title", "기기 페어링" },
        { "Sync_Pair_Desc", "연동 동기화에는 직접 마련한 서버(NovaraSync, 설치 패키지에 포함)가 필요합니다. 서버가 없어도 Novara의 다른 기능은 모두 정상 동작하며, 설정 방법은 왼쪽 아래 「배포 도움말」을 참고하세요. 먼저 서버에서 동기화 공간을 만든 뒤 아래 항목을 입력하세요. 공간 키를 비워 두면 첫 기기로 간주되어 이 PC에서 생성됩니다. 기존 공간에 참여할 때는 그 공간을 만든 기기에 표시된 키를 입력하세요." },
